            Temporal *t = BlobToTemporal(a);
            STBox *bx = BlobToStbox(b);
            double r = nad_tgeo_stbox(t, bx);
            free(t); free(bx);
            if (r == std::numeric_limits<double>::max()) { mask.SetInvalid(idx); return double(); }
